// Golden tests for geometry: GeomUtil, GLUtil matrix math, PointDouble, Segment, MinMax*,
// ColorUtil, DisplayUtil and the Java/JS rounding helper.
// Goldens generated by tools/fixtures/core/geom.js from the reference JS implementation.
import Foundation
import ORIPACore

private struct GeomFixture: Decodable {
    struct Call: Decodable {
        let fn: String
        let args: [Double]
        let expected: [Double]
    }

    struct PolygonCall: Decodable {
        let z: Int
        let poly1: [[Double]]
        let poly2: [[Double]]
        let expected: Int
    }

    struct GLUtilJSON: Decodable {
        let MAX_FACE_SETS: Int
        let MAX_LINE_SETS: Int
        let MAX_LINES_PER_SET: Int
        let identity: [Double]
        let translated: [Double]
        let translatedPoint: [Double]
        let objectPoint: [Double]
        let objectPointFloat: [Double]
        let rotate90: [Double]
        let rotatedPoint: [Double]
        let inverseRotate90: [Double]
        let rotateTimesInverse: [Double]
        let scaled: [Double]
        let scaledPoint: [Double]
        let floatMatrixRotate90: [Double]
        let floatMatrixPoint: [Double]
        let mirrorMatrix: [Double]
        let mirrorLine: [Double]
        let mirrorBack: [Double]
        let mirrorFixed: [Double]
    }

    struct PointDoubleJSON: Decodable {
        let length: Double
        let staticLength: Double
        let hashCode: Int
        let hashCodes: [Int]
        let equalsSame: Int
        let equalsDifferent: Int
        let minDistance: Double
        let toString: String
    }

    struct SegmentJSON: Decodable {
        let hashCode: Int
        let equalsSame: Int
        let equalsReversed: Int
        let minDistancePerpendicular: Double
        let minDistanceEndpoint: Double
        let minDistances: [Double]
    }

    struct MinMaxDoubleJSON: Decodable {
        let empty: [Double]
        let custom: [Double]
        let readArray: [Double]
        let centers: [Double]
    }

    struct MinMaxFloatJSON: Decodable {
        let empty: [Double]
        let readArray: [Double]
        let centers: [Double]
    }

    struct ColorUtilJSON: Decodable {
        let rainbow: [Int]
        let intToStringRgb: [String]
        let intToStringRgbNoHash: [String]
        let rgbFloat: [Double]
        let hueAngleDeg: [Double]
        let saturatedHue: [Int]
    }

    struct DisplayUtilJSON: Decodable {
        let pixelFromDp: [Double]
        let gridColumnCount: [Int]
    }

    struct JSRoundJSON: Decodable {
        let value: Double
        let round: Double
        let roundTimes1000: Double
    }

    let calls: [Call]
    let polygonCalls: [PolygonCall]
    let glutil: GLUtilJSON
    let pointDouble: PointDoubleJSON
    let segment: SegmentJSON
    let minMaxDouble: MinMaxDoubleJSON
    let minMaxFloat: MinMaxFloatJSON
    let colorUtil: ColorUtilJSON
    let displayUtil: DisplayUtilJSON
    let jsRound: [JSRoundJSON]
}

private func point(_ values: [Double]) -> PointDouble {
    PointDouble(values[0], values[1])
}

/// Evaluates one golden `GeomUtil` call with the same argument packing as the JS generator.
private func evaluateGeomCall(_ call: GeomFixture.Call) -> [Double]? {
    let a = call.args
    switch call.fn {
    case "getDistance":
        return [GeomUtil.getDistance(a[0], a[1], a[2], a[3])]
    case "getDistanceSquared":
        return [GeomUtil.getDistanceSquared(a[0], a[1], a[2], a[3])]
    case "getAngleRadians":
        return [GeomUtil.getAngleRadians(a[0], a[1], a[2], a[3])]
    case "getAngleRadBetweenLines":
        return [GeomUtil.getAngleRadBetweenLines(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])]
    case "getDotProductLines2D":
        return [GeomUtil.getDotProductLines2D(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])]
    case "getLineIntersect":
        guard let p = GeomUtil.getLineIntersect(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7]) else { return [] }
        return [p.x, p.y]
    case "getSegmentIntersect":
        guard let p = GeomUtil.getSegmentIntersect(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7]) else { return [] }
        return [p.x, p.y]
    case "isParallel":
        return [Double(boolValue(GeomUtil.isParallel(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])))]
    case "isCollinear":
        return [Double(boolValue(GeomUtil.isCollinear(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])))]
    case "getDistanceBetweenParallel":
        return [GeomUtil.getDistanceBetweenParallel(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7])]
    case "getPerpendicularDistance":
        return [GeomUtil.getPerpendicularDistance(a[0], a[1], a[2], a[3], a[4], a[5])]
    case "getPerpendicularIntersect":
        let p = GeomUtil.getPerpendicularIntersect(a[0], a[1], a[2], a[3], a[4], a[5])
        return [p.x, p.y]
    case "isInRange":
        return [Double(boolValue(GeomUtil.isInRange(a[0], a[1], a[2])))]
    case "isInRangePoint":
        return [Double(boolValue(GeomUtil.isInRange(point([a[0], a[1]]), point([a[2], a[3]]), point([a[4], a[5]]))))]
    case "isInRangeInt":
        return [Double(boolValue(GeomUtil.isInRangeInt(Int(a[0]), Int(a[1]), Int(a[2]))))]
    case "clamp":
        return [Double(GeomUtil.clamp(Int(a[0]), Int(a[1])))]
    case "constrain":
        return [GeomUtil.constrain(a[0], a[1], a[2])]
    case "getDeterminant3x3":
        return [GeomUtil.getDeterminant3x3(a)]
    case "isCCW":
        return [Double(boolValue(GeomUtil.isCCW(point([a[0], a[1]]), point([a[2], a[3]]), point([a[4], a[5]]))))]
    case "getIncenter":
        let p = GeomUtil.getIncenter(point([a[0], a[1]]), point([a[2], a[3]]), point([a[4], a[5]]))
        return [p.x, p.y]
    case "getPolygonArea":
        var polygon: [PointDouble] = []
        var index = 0
        while index + 1 < a.count {
            polygon.append(point([a[index], a[index + 1]]))
            index += 2
        }
        return [GeomUtil.getPolygonArea(polygon)]
    case "isPointInOriginSquare":
        return [Double(boolValue(GeomUtil.isPointInOriginSquare(point([a[0], a[1]]), a[2], a[3])))]
    case "isPointInOriginRectangle":
        return [Double(boolValue(GeomUtil.isPointInOriginRectangle(point([a[0], a[1]]), a[2], a[3], a[4])))]
    case "isPointOutsideOriginSquare":
        return [Double(boolValue(GeomUtil.isPointOutsideOriginSquare(point([a[0], a[1]]), a[2], a[3])))]
    case "isPointOutsideOriginRectangle":
        return [Double(boolValue(GeomUtil.isPointOutsideOriginRectangle(point([a[0], a[1]]), a[2], a[3], a[4])))]
    case "isPointInOriginHexagon":
        return [Double(boolValue(GeomUtil.isPointInOriginHexagon(point([a[0], a[1]]), a[2], a[3])))]
    case "getDefaultIntKey":
        return [Double(GeomUtil.getDefaultIntKey(a[0]))]
    case "getIntKey":
        return [Double(GeomUtil.getIntKey(Int(a[0]), a[1]))]
    case "isPointInConvexPolygon":
        var polygon: [PointDouble] = []
        var index = 6
        while index + 1 < a.count {
            polygon.append(point([a[index], a[index + 1]]))
            index += 2
        }
        return [Double(boolValue(GeomUtil.isPointInConvexPolygon(
            Int(a[0]), a[1] != 0, point([a[2], a[3]]), point([a[4], a[5]]), polygon
        )))]
    default:
        return nil
    }
}

enum GeomTests {
    static var all: [TestSuite] {
        [TestSuite("CoreModel.Geom") { harness in
            let fixture = try Fixtures.decode(GeomFixture.self, "Fixtures/core/geom.json")

            // MARK: GeomUtil calls
            for call in fixture.calls {
                guard let actual = evaluateGeomCall(call) else {
                    harness.fail("unhandled geom call \(call.fn)")
                    continue
                }
                harness.expectEqual(actual.count, call.expected.count, "\(call.fn) count")
                for index in 0..<min(actual.count, call.expected.count) {
                    harness.expectClose(actual[index], call.expected[index], accuracy: 1e-9, "\(call.fn)[\(index)]")
                }
            }

            // MARK: doPolygonLinesCross
            for call in fixture.polygonCalls {
                let polygon1 = call.poly1.map { point($0) }
                let polygon2 = call.poly2.map { point($0) }
                harness.expectEqual(
                    boolValue(GeomUtil.doPolygonLinesCross(call.z != 0, polygon1, polygon2)),
                    call.expected,
                    "doPolygonLinesCross"
                )
            }

            // MARK: GLUtil constants / buffers / error no-op
            let gl = fixture.glutil
            harness.expectEqual(GLUtil.MAX_FACE_SETS, gl.MAX_FACE_SETS, "MAX_FACE_SETS")
            harness.expectEqual(GLUtil.MAX_LINE_SETS, gl.MAX_LINE_SETS, "MAX_LINE_SETS")
            harness.expectEqual(GLUtil.MAX_LINES_PER_SET, gl.MAX_LINES_PER_SET, "MAX_LINES_PER_SET")
            GLUtil.checkGlError("x") // must not throw / trap
            harness.expectEqual(GLUtil.getFloatBuffer([1, 2]).count, 2, "getFloatBuffer")
            harness.expectEqual(GLUtil.getShortBuffer([1, 2]).count, 2, "getShortBuffer")
            harness.expectEqual(GLUtil.getByteBuffer([1, 2]).count, 2, "getByteBuffer")

            // MARK: GLUtil matrices + point transforms
            var identity = [Double](repeating: 0, count: 16)
            GLUtil.setIdentityM(&identity, 0)
            expectEqualMatrix(harness, identity, gl.identity, accuracy: 1e-15, "identity")
            var translated = identity
            GLUtil.translateM(&translated, 0, 10, 20, 0)
            expectEqualMatrix(harness, translated, gl.translated, accuracy: 1e-12, "translated")

            let pTranslated = GLUtil.getTransformedPointDouble(translated, 3, 4)
            expectCloseArray(harness, [pTranslated.x, pTranslated.y], gl.translatedPoint, "translated point")
            let pObject = GLUtil.getObjectPointFromWorldPointDouble(translated, 13, 24)
            expectCloseArray(harness, [pObject.x, pObject.y], gl.objectPoint, "object point")
            let pObjectFloat = GLUtil.getObjectPointFromWorldPointFloat(translated, 13, 24)
            expectCloseArray(harness, [pObjectFloat.x, pObjectFloat.y], gl.objectPointFloat, "object point float")

            var rotate = [Double](repeating: 0, count: 16)
            GLUtil.setIdentityM(&rotate, 0)
            GLUtil.rotateM(&rotate, 0, 90, 0, 0, 1)
            expectEqualMatrix(harness, rotate, gl.rotate90, accuracy: 1e-12, "rotate90")
            let pRotated = GLUtil.getTransformedPointDouble(rotate, 1, 0)
            expectCloseArray(harness, [pRotated.x, pRotated.y], gl.rotatedPoint, accuracy: 1e-6, "rotated point")

            var inverse = [Double](repeating: 0, count: 16)
            let inverted = GLUtil.invertM(&inverse, 0, rotate, 0)
            harness.expect(inverted, "invertM returns true")
            expectEqualMatrix(harness, inverse, gl.inverseRotate90, accuracy: 1e-12, "inverse rotate90")
            var product = [Double](repeating: 0, count: 16)
            GLUtil.multiplyMM(&product, 0, rotate, 0, inverse, 0)
            expectEqualMatrix(harness, product, gl.rotateTimesInverse, accuracy: 1e-12, "rotate * inverse")

            var scaled = [Double](repeating: 0, count: 16)
            GLUtil.setIdentityM(&scaled, 0)
            GLUtil.scaleM(&scaled, 0, 2, 3, 1)
            expectEqualMatrix(harness, scaled, gl.scaled, accuracy: 1e-12, "scaled")
            let pScaled = GLUtil.getTransformedPointDouble(scaled, 1, 1)
            expectCloseArray(harness, [pScaled.x, pScaled.y], gl.scaledPoint, "scaled point")

            // [Float] matrix overload (Android float[] path)
            let floatMatrix = gl.floatMatrixRotate90.map { Float($0) }
            let pFloat = GLUtil.getTransformedPointDouble(floatMatrix, Float(1), Float(0))
            expectCloseArray(harness, [pFloat.x, pFloat.y], gl.floatMatrixPoint, accuracy: 1e-6,
                             "float matrix point")

            // MARK: GeomUtil mirror transform
            let mirror = GeomUtil.getMirrorTransformMatrix(PointDouble(-100, 0), PointDouble(100, 0))
            expectEqualMatrix(harness, mirror, gl.mirrorMatrix, accuracy: 1e-9, "mirror matrix")
            let mirroredLine = GeomUtil.getTransformedLine(PointDouble(10, 20), PointDouble(-30, 5), mirror)
            expectCloseArray(
                harness,
                [mirroredLine.start.x, mirroredLine.start.y, mirroredLine.end.x, mirroredLine.end.y],
                gl.mirrorLine, accuracy: 1e-6, "mirror line"
            )
            let mirroredBack = GeomUtil.getTransformedLine(mirroredLine.start, mirroredLine.end, mirror)
            expectCloseArray(
                harness,
                [mirroredBack.start.x, mirroredBack.start.y, mirroredBack.end.x, mirroredBack.end.y],
                gl.mirrorBack, accuracy: 1e-6, "mirror involution"
            )
            let fixed = GeomUtil.getTransformedLine(PointDouble(0, 0), PointDouble(50, 50), mirror)
            expectCloseArray(harness, [fixed.start.x, fixed.start.y], gl.mirrorFixed, accuracy: 1e-6,
                             "mirror fixed point")
            let fixedBack = GeomUtil.getTransformedLine(PointDouble(0, 0), PointDouble(50, 50), mirror)
            harness.expectClose(fixedBack.start.x, 0, accuracy: 1e-6, "mirror second fixed x")

            // MARK: PointDouble
            let pd = PointDouble(3, 4)
            harness.expectClose(pd.length(), fixture.pointDouble.length, "PointDouble.length")
            harness.expectClose(PointDouble.length(3, 4), fixture.pointDouble.staticLength, "PointDouble static length")
            harness.expectEqual(pd.hashCode(), fixture.pointDouble.hashCode, "PointDouble.hashCode")
            harness.expectEqual(PointDouble(0, 0).hashCode(), fixture.pointDouble.hashCodes[0], "hash (0,0)")
            harness.expectEqual(PointDouble(1, 2).hashCode(), fixture.pointDouble.hashCodes[1], "hash (1,2)")
            harness.expectEqual(PointDouble(-3.5, 7.25).hashCode(), fixture.pointDouble.hashCodes[2], "hash (-3.5,7.25)")
            harness.expectEqual(boolValue(pd.equals(PointDouble(3, 4))), fixture.pointDouble.equalsSame, "PointDouble.equals same")
            harness.expectEqual(boolValue(pd.equals(PointDouble(3, 5))), fixture.pointDouble.equalsDifferent, "PointDouble.equals different")
            harness.expectClose(pd.getMinDistance(PointDouble(0, 0)), fixture.pointDouble.minDistance, "PointDouble.getMinDistance")
            harness.expectEqual(pd.toString(), fixture.pointDouble.toString, "PointDouble.toString")
            harness.expectEqual(boolValue(pd.equals(SphereLike())), 0, "PointDouble.equals other type")

            // MARK: Segment
            let segment = Segment<PointDouble>(PointDouble(0, 0), PointDouble(10, 0))
            harness.expectEqual(segment.hashCode(), fixture.segment.hashCode, "Segment.hashCode")
            let segmentSame = Segment<PointDouble>(PointDouble(0, 0), PointDouble(10, 0))
            harness.expectEqual(boolValue(segment.equals(segmentSame)), fixture.segment.equalsSame, "Segment.equals same")
            let segmentReversed = Segment<PointDouble>(PointDouble(10, 0), PointDouble(0, 0))
            harness.expectEqual(boolValue(segment.equals(segmentReversed)), fixture.segment.equalsReversed, "Segment.equals reversed")
            harness.expectClose(segment.getMinDistance(PointDouble(5, 3)), fixture.segment.minDistancePerpendicular,
                                "Segment perpendicular distance")
            harness.expectClose(segment.getMinDistance(PointDouble(-2, 0)), fixture.segment.minDistanceEndpoint,
                                "Segment endpoint distance")
            let segmentPoints = [
                PointDouble(5, 3), PointDouble(-2, 0), PointDouble(12, 0), PointDouble(5, -7),
            ]
            for index in 0..<segmentPoints.count {
                harness.expectClose(segment.getMinDistance(segmentPoints[index]),
                                    fixture.segment.minDistances[index], "Segment minDistance[\(index)]")
            }

            // MARK: MinMaxDouble
            harness.expectEqual(MinMaxDouble().toArray(), fixture.minMaxDouble.empty, "MinMaxDouble empty")
            harness.expectEqual(MinMaxDouble(1, 2, 3, 4).toArray(), fixture.minMaxDouble.custom, "MinMaxDouble custom")
            harness.expectEqual(MinMaxDouble.readArray([-1, -2, 5, 6]).toArray(), fixture.minMaxDouble.readArray,
                                "MinMaxDouble readArray")
            let mm = MinMaxDouble(0, 0, 10, 20)
            let mmCenters: [Double] = [
                mm.getCenterX(), mm.getCenterY(), mm.getHalfSizeX(), mm.getHalfSizeY(), mm.getMaxHalfSize(),
            ]
            expectCloseArray(harness, mmCenters, fixture.minMaxDouble.centers, "MinMaxDouble centers")

            // MARK: MinMaxFloat
            harness.expectEqual(MinMaxFloat().toArray().map(Double.init), fixture.minMaxFloat.empty,
                                "MinMaxFloat empty")
            harness.expectEqual(MinMaxFloat.readArray([-1.5, -2.5, 5.5, 6.5]).toArray().map(Double.init),
                                fixture.minMaxFloat.readArray, "MinMaxFloat readArray")
            // JS/Java MinMaxFloat has no value constructor: create empty and assign fields.
            let mmf = MinMaxFloat()
            mmf.minX = 0
            mmf.minY = 0
            mmf.maxX = 10
            mmf.maxY = 20
            let mmfCenters: [Double] = [
                Double(mmf.getCenterX()), Double(mmf.getCenterY()), Double(mmf.getHalfSizeX()),
                Double(mmf.getMaxHalfSize()),
            ]
            expectCloseArray(harness, mmfCenters, fixture.minMaxFloat.centers, "MinMaxFloat centers")

            // MARK: ColorUtil
            let cu = fixture.colorUtil
            harness.expectEqual(ColorUtil.getRainbow(), cu.rainbow, "ColorUtil.getRainbow")
            harness.expectEqual(cu.intToStringRgb.count, 5, "intToStringRgb cases")
            let rgbInputs = [-65536, 0x123456, 0, -1, 0x00AB_CDEF]
            for index in 0..<rgbInputs.count {
                harness.expectEqual(ColorUtil.intToStringRgb(rgbInputs[index]), cu.intToStringRgb[index],
                                    "intToStringRgb[\(index)]")
            }
            harness.expectEqual(ColorUtil.intToStringRgbNoHash(0x123456), cu.intToStringRgbNoHash[0],
                                "intToStringRgbNoHash 0x123456")
            harness.expectEqual(ColorUtil.intToStringRgbNoHash(-65536), cu.intToStringRgbNoHash[1],
                                "intToStringRgbNoHash -65536")
            let rgbFloat = ColorUtil.getRgbFloatFromInt(0xFF8000)
            expectCloseArray(harness, rgbFloat.map(Double.init), cu.rgbFloat, "ColorUtil.getRgbFloatFromInt")
            let hueInputs = [0xFF0000, 0x00FF00, 0x0000FF, 0xFFFFFF, 0x000000]
            for index in 0..<hueInputs.count {
                harness.expectClose(ColorUtil.getHueAngleDeg(hueInputs[index]), cu.hueAngleDeg[index],
                                    accuracy: 1e-6, "getHueAngleDeg[\(index)]")
            }
            let hueValues = [0.0, 120.0, 240.0, 60.0, 300.0]
            for index in 0..<hueValues.count {
                harness.expectEqual(ColorUtil.getSaturatedHue(hueValues[index]), cu.saturatedHue[index],
                                    "getSaturatedHue[\(index)]")
            }

            // MARK: DisplayUtil
            let du = fixture.displayUtil
            harness.expectClose(DisplayUtil.getPixelFromDp(16), du.pixelFromDp[0], "getPixelFromDp(16)")
            harness.expectClose(DisplayUtil.getPixelFromDp(2, 16), du.pixelFromDp[1], "getPixelFromDp(2,16)")
            harness.expectClose(DisplayUtil.getPixelFromDp(3, 5), du.pixelFromDp[2], "getPixelFromDp(3,5)")
            harness.expectEqual(DisplayUtil.getGridColumnCount(320.0, 100.0), du.gridColumnCount[0], "gridColumnCount(320,100)")
            harness.expectEqual(DisplayUtil.getGridColumnCount(768.0, 2.0, 100.0), du.gridColumnCount[1], "gridColumnCount(768,2,100)")
            harness.expectEqual(DisplayUtil.getGridColumnCount(100.0, 300.0), du.gridColumnCount[2], "gridColumnCount(100,300)")

            // MARK: JavaMath rounding (JS Math.round semantics)
            for entry in fixture.jsRound {
                harness.expectClose(JavaMath.round(entry.value), entry.round, "JavaMath.round(\(entry.value))")
                harness.expectClose(Double(JavaMath.roundToInt(entry.value * 1000)), entry.roundTimes1000,
                                    "JavaMath.roundToInt(\(entry.value * 1000))")
            }
        }]
    }
}

/// Dummy class used to check `PointDouble.equals` rejects other types (mirrors JS `instanceof`).
private final class SphereLike {}
